import Foundation

/// Emits one ``Theme`` as CSS custom properties, scoped to `[data-theme-name="<id>"]` so several themes can
/// coexist on a page.
///
/// Nothing in the output is typed here: every colour, weight, size and font comes from the theme, and the
/// header carries the theme's content hash. A test checks that every colour literal in a generated file is a
/// value of its theme.
///
/// ### Blocks, in cascade order
/// 1. the light values, with the structure (rules, layout, marks, type);
/// 2. `prefers-contrast: more`, light;
/// 3. `prefers-color-scheme: dark`, unless the element is pinned light (`data-theme="light"` or
///    `data-bs-theme="light"`);
/// 4. the explicit dark selectors, which match the themed element or any element inside a dark one;
/// 5. `prefers-contrast: more` with the dark scheme;
/// 6. `prefers-contrast: more` with the explicit dark selectors.
///
/// Blocks 3 to 6 exist only for a theme that declares ``AppearanceSupport/both``; a block with nothing in it
/// is left out. A light-only theme says `color-scheme: light`, a fixed-dark one `color-scheme: dark`.
///
/// Increased-contrast blocks carry only the colours that have a measured increased-contrast value: the
/// others carry through, as ``Adaptive/value(in:increasedContrast:)`` does.
///
/// The card chrome is emitted as `--card-chrome` and the `--card-surface`, `--card-top-rule`, `--card-top-color`, `--card-min` and `--card-gap` properties derived from it.
///
/// Not emitted as CSS: value-label and series-labelling flags, axis placement and number formats (the value halo, card
/// border and padding, reference-label gap, mark default fill and emphasis are emitted). They are not
/// presentational properties a stylesheet can use; the theme's JSON carries them.
public enum ThemeCSSEmitter {
    /// The complete stylesheet for a theme, ending in a newline.
    ///
    /// - Throws: An encoding error if the theme cannot be encoded for its content hash (a NaN weight, for instance).
    public static func emit(_ theme: Theme) throws -> String {
        let scope = "[data-theme-name=\"\(theme.id)\"]"
        let notPinnedLight = ":not([data-theme=\"light\"]):not([data-bs-theme=\"light\"])"
        let hash = try ThemeCodec.fingerprint(of: theme)
        var lines = ["/* Generated by design-tokens. Do not edit. Theme: \(theme.id) (\(theme.name)) | DesignTokens \(DesignTokens.version) | System colours: snapshot of \(Snapshot.systemRelease) | hash fnv1a64:\(hash) */"]

        let baseScheme = theme.appearances == .fixedDark ? "dark" : "light"
        lines.append("\(scope) {")
        lines.append("  color-scheme: \(baseScheme);")
        lines.append(contentsOf: colourDeclarations(theme, appearance: .light, increased: false, only: .all))
        lines.append(contentsOf: structureDeclarations(theme))
        lines.append("}")

        let increasedLight = colourDeclarations(theme, appearance: .light, increased: true, only: .increasedOnly)
        if !increasedLight.isEmpty {
            lines.append("@media (prefers-contrast: more) {")
            lines.append("  \(scope) {")
            lines.append(contentsOf: increasedLight.map { "  " + $0 })
            lines.append("  }")
            lines.append("}")
        }

        guard theme.appearances == .both else { return lines.joined(separator: "\n") + "\n" }

        let dark = ["  color-scheme: dark;"] + colourDeclarations(theme, appearance: .dark, increased: false, only: .darkOnly)
        let explicit = ["\(scope)[data-theme=\"dark\"]", "\(scope)[data-bs-theme=\"dark\"]",
                        "[data-theme=\"dark\"] \(scope)", "[data-bs-theme=\"dark\"] \(scope)"]
        lines.append("@media (prefers-color-scheme: dark) {")
        lines.append("  \(scope)\(notPinnedLight) {")
        lines.append(contentsOf: dark.map { "  " + $0 })
        lines.append("  }")
        lines.append("}")
        lines.append(explicit.joined(separator: ",\n") + " {")
        lines.append(contentsOf: dark)
        lines.append("}")

        let increasedDark = colourDeclarations(theme, appearance: .dark, increased: true, only: .increasedOnly)
        if !increasedDark.isEmpty {
            lines.append("@media (prefers-contrast: more) and (prefers-color-scheme: dark) {")
            lines.append("  \(scope)\(notPinnedLight) {")
            lines.append(contentsOf: increasedDark.map { "  " + $0 })
            lines.append("  }")
            lines.append("}")
            lines.append("@media (prefers-contrast: more) {")
            lines.append("  " + explicit.joined(separator: ",\n  ") + " {")
            lines.append(contentsOf: increasedDark.map { "  " + $0 })
            lines.append("  }")
            lines.append("}")
        }
        return lines.joined(separator: "\n") + "\n"
    }

    // MARK: Colours

    private enum Selection {
        /// Every colour (the light block).
        case all
        /// Only a colour that has an increased-contrast value for the appearance.
        case increasedOnly
        /// Every colour, and the dark ramps that exist (the dark block).
        case darkOnly
    }

    private static func colourDeclarations(_ theme: Theme, appearance: Appearance, increased: Bool,
                                           only selection: Selection) -> [String] {
        func has(_ adaptive: Adaptive) -> Bool {
            guard selection == .increasedOnly else { return true }
            return (appearance == .dark ? adaptive.darkIncreased : adaptive.lightIncreased) != nil
        }
        func value(_ adaptive: Adaptive) -> ColorValue {
            adaptive.value(in: appearance, increasedContrast: increased)
        }
        var out: [String] = []
        let palette = theme.palette
        for role in ColorRole.allCases where has(palette[role]) {
            out.append(contentsOf: withRGB("--\(kebab(role.rawValue))", value(palette[role])))
        }
        for (index, entry) in palette.series.enumerated() where has(entry.color) {
            out.append("  --series-\(index + 1): \(value(entry.color).hex);")
        }
        for key in palette.extras.keys.sorted() {
            guard let adaptive = palette.extras[key], has(adaptive) else { continue }
            out.append(contentsOf: withRGB("--extra-\(kebab(key))", value(adaptive)))
        }
        guard selection != .increasedOnly else { return out }
        func ramp(_ name: String, _ ramp: Ramp) {
            let steps = appearance == .dark ? ramp.dark : ramp.light
            for (index, step) in (steps ?? []).enumerated() {
                out.append("  --\(name)-\(index + 1): \(step.hex);")
            }
        }
        ramp("sequential", palette.sequential)
        ramp("diverging", palette.diverging)
        for name in palette.extraRamps.keys.sorted() {
            if let extra = palette.extraRamps[name] { ramp("ramp-\(kebab(name))", extra) }
        }
        return out
    }

    private static func withRGB(_ name: String, _ color: ColorValue) -> [String] {
        ["  \(name): \(color.hex);", "  \(name)-rgb: \(color.rgb.red), \(color.rgb.green), \(color.rgb.blue);"]
    }

    // MARK: Structure

    private static func structureDeclarations(_ theme: Theme) -> [String] {
        let s = theme.structure
        var out: [String] = []
        func add(_ name: String, _ value: String) { out.append("  --\(name): \(value);") }
        func px(_ value: Double) -> String { "\(CSSNumber.string(value))px" }
        func number(_ value: Double) -> String { CSSNumber.string(value) }

        let rules = s.rules
        add("rule-title", px(rules.title.weight))
        add("rule-title-position", kebab(rules.title.position.rawValue))
        add("rule-title-color", "var(--\(kebab(rules.title.colour.rawValue)))")
        add("rule-title-inset", px(rules.title.inset))
        if let gap = rules.title.gapAfter { add("rule-title-gap-after", px(gap)) }
        add("rule-section", px(rules.section))
        add("rule-hairline", px(rules.hairline))
        add("rule-gridline", px(rules.gridline))
        add("rule-baseline", px(rules.baseline))
        add("rule-baseline-color", "var(--\(kebab(rules.baselineColour.rawValue)))")
        add("rule-page", px(rules.page))
        add("rule-reference", px(rules.reference.weight))
        add("rule-reference-dash", rules.reference.dash.isEmpty ? "none" : rules.reference.dash.map(number).joined(separator: " "))
        add("rule-plot-border", px(rules.plotBorder))
        add("rule-reference-color", "var(--\(kebab(rules.referenceColour.rawValue)))")
        add("rule-reference-label-color", "var(--\(kebab(rules.referenceLabelColour.rawValue)))")

        let layout = s.layout
        add("gutter", px(layout.gutter))
        add("space-unit", px(layout.baseUnit))
        add("columns", "\(layout.columns)")
        add("radius-container", px(layout.containerRadius))
        add("radius-control", px(layout.controlRadius))
        add("radius-annotation", px(layout.annotationRadius))
        add("margin-top", px(layout.margins.top))
        add("margin-leading", px(layout.margins.leading))
        add("margin-bottom", px(layout.margins.bottom))
        add("margin-trailing", px(layout.margins.trailing))
        add("gap-title", px(layout.gaps.title))
        add("gap-subtitle", px(layout.gaps.subtitle))
        add("gap-plot", px(layout.gaps.plot))
        add("gap-source", px(layout.gaps.source))
        add("gap-reference-label", px(layout.gaps.referenceLabel))
        add("card-border", px(layout.cardBorder))
        add("card-padding", px(layout.cardPadding))
        // The card chrome, and what a stylesheet needs from it. A custom property cannot branch, so the theme resolves the choice here
        // and components.css only reads the results. Ruled (Swiss): no surface, the section rule in ink across the top. Bordered: the
        // surface, no top rule (the border is --card-border, in the rule colour). The grid's column minimum is 88 base units (352 px at
        // 4 px), so three cards fit a 1200 px page with its padding, and one fits a phone.
        add("card-chrome", layout.cardChrome.rawValue)
        add("card-min", px(layout.baseUnit * Double(BrowserSupport.Breakpoints.cardMinimumWidthInBaseUnits)))
        add("card-gap", "var(--gutter)")
        switch layout.cardChrome {
        case .ruled:
            add("card-surface", "transparent")
            add("card-top-rule", "var(--rule-section)")
            add("card-top-color", "var(--ink)")
        case .bordered:
            add("card-surface", "var(--surface)")
            add("card-top-rule", "0px")
            add("card-top-color", "var(--rule)")
        }
        add("label-value-halo", px(s.labels.valueHalo))
        add("gridlines", kebab(layout.gridlines.rawValue))
        if let shadow = layout.shadow {
            add("shadow", "\(px(shadow.x)) \(px(shadow.y)) \(px(shadow.radius)) \(reference(shadow.colour))")
        } else {
            add("shadow", "none")
        }

        let marks = s.marks
        add("mark-line-width", px(marks.lineWidth))
        add("mark-point-size", px(marks.pointSize))
        add("mark-band-opacity", number(marks.bandOpacity))
        add("mark-selected-line-width", px(marks.selectedLineWidth))
        add("mark-area-opacity", number(marks.areaOpacity))
        add("mark-fill-opacity", number(marks.fillOpacity))
        add("mark-detail-line-width", px(marks.detailLineWidth))
        add("mark-bar-fill", kebab(marks.barFill.rawValue))
        add("mark-bar-width-ratio", number(marks.barWidthRatio))
        add("mark-bar-corner-radius", px(marks.barCornerRadius))
        add("mark-line-end", kebab(marks.lineEnd.rawValue))
        add("mark-default-fill", kebab(marks.defaultFill.rawValue))
        add("mark-default-emphasis", kebab(marks.defaultEmphasis.rawValue))
        add("mark-emphasis-fill", "var(--\(kebab(marks.emphasisFill.rawValue)))")
        if let tag = marks.tagMark {
            add("mark-tag-width", px(tag.width))
            add("mark-tag-height", px(tag.height))
            add("mark-tag-color", "var(--\(kebab(tag.colour.rawValue)))")
        }

        add("font-sans", FontStack.sans)
        add("font-mono", FontStack.mono)
        add("font-serif-new-york", FontStack.serifNewYork)
        add("font-serif-garamond", FontStack.serifGaramond)
        for role in TypeRole.allCases {
            let spec = s.type[role]
            let prefix = role.isUIRole ? "type-\(role == .uiTitle ? "title" : role.rawValue)" : "chart-\(kebab(role.rawValue))"
            add("\(prefix)-family", family(spec.family))
            // The display role at the package's display size is the fluid role, as in tokens.css.
            let fluid = role == .display && spec.size == TypeStyle.display.points ? TypeStyle.display.fluid : nil
            add("\(prefix)-size", fluid?.css ?? px(spec.size))
            add("\(prefix)-line", number(spec.lineHeight))
            add("\(prefix)-weight", "\(spec.weight)")
            add("\(prefix)-tracking", spec.tracking == 0 ? "0" : "\(number(spec.tracking))em")
            add("\(prefix)-transform", spec.uppercase ? "uppercase" : "none")
            add("\(prefix)-style", spec.italic ? "italic" : "normal")
        }
        return out
    }

    private static func family(_ ref: FontFamilyRef) -> String {
        switch ref {
        case .sans: FontStack.sans
        case .mono: FontStack.mono
        case .serifNewYork: FontStack.serifNewYork
        case .serifGaramond: FontStack.serifGaramond
        case .named(let name, let fallback): "\"\(name)\", \(family(fallback))"
        }
    }

    /// A colour reference as a CSS value: the variable, or the variable at an opacity.
    private static func reference(_ ref: ColourReference) -> String {
        let name = ColorRole(rawValue: ref.source).map { "--\(kebab($0.rawValue))" } ?? "--extra-\(kebab(ref.source))"
        guard ref.opacity < 1 else { return "var(\(name))" }
        return "color-mix(in srgb, var(\(name)) \(CSSNumber.string((ref.opacity * 100).rounded()))%, transparent)"
    }

    /// `secondaryInk` to `secondary-ink`; an id or key that already has hyphens is left as it is.
    static func kebab(_ name: String) -> String {
        var out = ""
        for character in name {
            if character.isUppercase { out += "-" + character.lowercased() } else { out.append(character) }
        }
        return out
    }
}
